fn io_probe(c: &Connection) -> Option<(std::time::Instant, i32, u64)> {
 if std::env::var_os("MESH_TALK_TRACE_READS").is_none() { return None; }
 let (mut n, mut high)=(0,0);
 unsafe { rusqlite::ffi::sqlite3_db_status(c.handle(),rusqlite::ffi::SQLITE_DBSTATUS_CACHE_MISS,&mut n,&mut high,0); }
